 "content": "from collections import Counter


def transform(grid):
    """Decode the dominant non-background symbol into its 3x3 marker."""
    counts = Counter(cell for row in grid for cell in row if cell != 0)
    if not counts:
        return [[0, 0, 0] for _ in range(3)]
    dominant = counts.most_common(1)[0][0]
    markers = {
        1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
        2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
        3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
    }
    return [row[:] for row in markers.get(dominant, [[0, 0, 0] for _ in range(3)])]
"
